function relevance(text,keys){const s=String(text||'').toLowerCase();return keys.reduce((n,k)=>n+(s.includes(k)?1:0),0)}
function rankedLines(text,keys){return bullets(text).map((line,index)=>({line,index,score:relevance(line,keys)})).sort((a,b)=>b.score-a.score||a.index-b.index).map(x=>x.line)}
function tailoredLocalHtml(){const p=state.profile,j=state.job,ks=words(),jobName=j.jobTitle||p.target||'目标岗位';const relevant=p.experiences.map((x,index)=>({...x,index,score:relevance(Object.values(x).join(' '),ks),detailLines:rankedLines(x.details,ks)})).sort((a,b)=>b.score-a.score||a.index-b.index);const matched=ks.filter(k=>corpus().includes(k)).slice(0,8);const summary=`面向${jobName}方向，具备${matched.slice(0,4).join('、')||'相关项目执行与协作'}经验。以下内容由事实资料库按当前岗位重新组织，投递前请逐项确认。`;const exp=relevant.map(x=>`<div class="resume-item"><header><h4>${esc(x.title||'未命名经历')}｜${esc(x.role||'')}</h4><span>${esc(x.date||'')}</span></header><ul>${x.detailLines.map(b=>`<li>${esc(b)}</li>`).join('')||'<li>待补充可验证的职责与成果</li>'}</ul></div>`).join('');const edu=rankedLines(p.education,ks),skills=rankedLines(p.skills,ks);document.querySelector('#resumePaper').innerHTML=`<div class="resume-head"><div class="resume-namebar"><div class="resume-name">${esc(p.name||'你的姓名')}</div><div class="resume-target">意向岗位：${esc(jobName)}${j.company?'｜'+esc(j.company):''}</div></div><div class="resume-contact"><span>电话：${esc(p.phone||'待填写')}</span><span>邮箱：${esc(p.email||'待填写')}</span><span>现所在地：${esc(p.location||'待填写')}</span><span>最高学历：${esc(p.degree||'待填写')}</span></div></div><div class="resume-body"><section class="resume-section"><h3><span>职业概述</span></h3><p>${esc(summary)}</p></section><section class="resume-section"><h3><span>岗位匹配</span></h3><p>${matched.join(' ｜ ')||'待补充与岗位相关的能力证据'}</p></section><section class="resume-section"><h3><span>相关经历</span></h3>${exp||'<p>请先在事实资料库添加经历。</p>'}</section><section class="resume-section"><h3><span>教育经历</span></h3>${edu.map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section><section class="resume-section"><h3><span>相关技能</span></h3>${skills.map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section></div>`;state.logs.push({time:new Date().toISOString(),event:'all_sections_tailored',job:jobName,keywords:ks.length});state.logs=state.logs.slice(-30);save();document.querySelector('#generationNote').textContent='已根据当前 JD 重排经历、教育和技能；本地 Codex 将继续优化表达。';go('preview')}
function templateAlignedHtml(){const p=state.profile,j=state.job,ks=words(),jobName=j.jobTitle||p.target||'目标岗位';const relevant=p.experiences.map((x,index)=>({...x,index,score:relevance(Object.values(x).join(' '),ks),detailLines:rankedLines(x.details,ks)})).sort((a,b)=>b.score-a.score||a.index-b.index);const matched=ks.filter(k=>corpus().includes(k)).slice(0,6);const summary=p.selfEvaluation||`具备${matched.join('、')||'相关项目执行与协作'}经验，简历内容将根据${jobName}岗位要求重新组织。`;const exp=relevant.map(x=>`<div class="resume-item"><header><h4>${esc(x.title||'未命名经历')}｜${esc(x.role||'')}</h4><span>${esc(x.date||'')}</span></header><ul>${x.detailLines.map(b=>`<li>${esc(b)}</li>`).join('')||'<li>待补充可验证的职责与成果</li>'}</ul></div>`).join('');const edu=rankedLines(p.education,ks),skills=rankedLines(p.skills,ks);const game=p.gameExperience?`<section class="resume-section"><h3><span>游戏经历</span></h3>${rankedLines(p.gameExperience,ks).map(x=>`<p>${esc(x)}</p>`).join('')}</section>`:'';const custom=(p.customSections||[]).filter(x=>x.title&&x.content).map(x=>`<section class="resume-section"><h3><span>${esc(x.title)}</span></h3>${rankedLines(x.content,ks).map(v=>`<p>${esc(v)}</p>`).join('')}</section>`).join('');document.querySelector('#resumePaper').innerHTML=`<div class="resume-head"><div class="resume-namebar"><div class="resume-name">${esc(p.name||'你的姓名')}</div><div class="resume-target">意向岗位：${esc(jobName)}${j.company?'｜'+esc(j.company):''}</div></div><div class="resume-contact"><span>电话：${esc(p.phone||'待填写')}</span><span>邮箱：${esc(p.email||'待填写')}</span>${p.age?`<span>年龄：${esc(p.age)}</span>`:''}<span>现所在地：${esc(p.location||'待填写')}</span><span>最高学历：${esc(p.degree||'待填写')}</span></div></div><div class="resume-body"><section class="resume-section"><h3><span>自我评价</span></h3><p>${esc(summary)}</p></section>${game}<section class="resume-section"><h3><span>教育经历</span></h3>${edu.map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section><section class="resume-section"><h3><span>项目经历</span></h3>${exp||'<p>请先在事实资料库添加经历。</p>'}</section><section class="resume-section"><h3><span>相关技能</span></h3>${skills.map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section>${custom}</div>`;state.logs.push({time:new Date().toISOString(),event:'template_aligned_tailor',job:jobName,keywords:ks.length});state.logs=state.logs.slice(-30);save();document.querySelector('#generationNote').textContent='已按原简历模板栏目，根据当前 JD 重排和润色内容。';go('preview')}
tailoredLocalHtml=templateAlignedHtml;
generateLocalHtml=templateAlignedHtml;
generate=async function(){if(!state.job.jdText.trim())return toast('请先填写岗位 JD');const analysis=window.analyzeCareerJob?.(),prior=state.resumes.find(x=>x.id===state.activeResumeId);try{let html;if(state.prefs.provider==='codex-local'){if(!codexConnected){document.querySelector('#aiSettingsDialog').showModal();throw new Error('本机 Codex 未连接，已停止生成；请启动本机桥接后重新检测')}toast('Codex 正在进行证据匹配、定向改写和质量检查…');const r=await fetch(LOCAL_BRIDGE+'/api/codex/rewrite',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mode:'tailor-all',profile:state.profile,originalResume:state.originalResume||null,portfolio:state.portfolio||null,job:state.job,careerAnalysis:analysis,priorResume:prior?{title:prior.title,text:prior.text}:null,tone:state.prefs.tone})});if(!r.ok||!(r.headers.get('content-type')||'').includes('application/json'))throw new Error('本机 Codex 桥接返回异常，请重新启动桥接');const d=await r.json();if(!r.ok)throw new Error(d.error||'调用失败');html=d.html}else{toast('AI 正在进行证据匹配、定向改写和质量检查…');html=await callConfiguredModel()}presentAiDraft(html);state.logs.push({time:new Date().toISOString(),event:'ai_draft_generated',provider:state.prefs.provider,job:state.job.jobTitle||'',track:analysis?.track||''});save();toast('AI 修改稿已生成，请检查红色修改和质量报告')}catch(e){state.logs.push({time:new Date().toISOString(),event:'ai_generate_error',provider:state.prefs.provider,message:e.message});save();toast(e.message)}};
document.querySelector('#generateResume').onclick=generate;
